/*
 * Bitmap fonts: fixed-cell (monospaced) 1-bit glyphs and a small UTF-8 decoder.
 *
 * The font tables themselves (core/gen/fonts_gen.c) are generated by
 * tools/gen_font.py from X11 BDF fonts (10x20, 7x14, 6x13); font_xlarge is the
 * 7x14 font pixel-doubled with smoothing and lives in flash bank 2. Each font
 * covers printable ASCII (codepoint 32 upward) plus the extra math symbols the
 * app uses, sorted by codepoint so lookup is a binary search. Glyph 0 is
 * therefore always the space character.
 *
 * Main caller: core/gfx.c (text drawing); gfx_text_width() measures a string
 * as utf8_len() * font->w because every glyph has the same advance.
 */
#ifndef FONT_H
#define FONT_H
#include <stdint.h>

/* One font. All glyphs share the same cell size; the advance is always w. */
typedef struct {
    uint8_t w, h;          /* cell size in pixels */
    uint8_t ascent;        /* baseline row from the top of the cell */
    uint8_t bytes_per_row; /* glyph row stride */
    uint16_t nglyphs;
    const uint16_t *cp;    /* sorted codepoints (all in the BMP) */
    const uint8_t *bits;   /* nglyphs * h * bytes_per_row, MSB = leftmost pixel */
} font_t;

extern const font_t font_large;  /* 10x20 */
extern const font_t font_medium; /* 7x14 */
extern const font_t font_small;  /* 6x13 */
extern const font_t font_xlarge; /* 14x28 (7x14 doubled): large-font mode, app/theme.h */

/* Glyph bitmap for a codepoint: h rows of bytes_per_row bytes, MSB = leftmost
 * pixel. Falls back to the '?' glyph if the codepoint is absent, and to glyph 0
 * (space) if '?' is absent too. Never returns NULL. O(log nglyphs). */
const uint8_t *font_glyph(const font_t *f, uint32_t cp);
/* Decode one UTF-8 codepoint from *s, advancing it past the bytes consumed.
 * Returns 0 at the terminating NUL (and does not advance). Malformed input
 * (an invalid lead byte, or a sequence cut short by a non-continuation byte or
 * the NUL) yields '?' and skips the bad bytes, so a loop over a string always
 * terminates. Overlong forms and surrogates are not rejected. */
uint32_t utf8_next(const char **s);
/* Number of codepoints in a UTF-8 string (= its width in cells). */
int utf8_len(const char *s);

#endif
